WITH deduped AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY event_type ORDER BY event_time NULLS LAST, id) AS latest_rank FROM web_events QUALIFY latest_rank = 1) SELECT session_id, CASE WHEN duration_sec >= 434 THEN 'LARGE' ELSE 'SMALL' END AS duration_sec_tier, (UNIX_TIMESTAMP(MAX(event_time)) - UNIX_TIMESTAMP(MIN(event_time))) / 60 AS span_minutes, COUNT(CASE WHEN event_type = 'add_to_cart' THEN 1 END) AS add_to_cart_count, AVG(duration_sec) FILTER (WHERE event_type = 'add_to_cart') AS add_to_cart_avg_duration_sec, COUNT_IF(event_type = 'add_to_cart') AS add_to_cart_events, COUNT(CASE WHEN page = '/product' THEN 1 END) AS product_count, SIZE(COLLECT_SET(page)) AS num_pages FROM deduped GROUP BY GROUPING SETS ((session_id, CASE WHEN duration_sec >= 434 THEN 'LARGE' ELSE 'SMALL' END), (session_id)) ORDER BY add_to_cart_count DESC NULLS FIRST
